import CopyButton from "@/components/CopyButton";
import { POSE_MODEL_FILES, POSE_MODEL_FILES_FETCHED_ON, type PoseModelFile, type PoseModelVariant } from "@/data/poseModelFiles";
import { formatDate } from "@/lib/posts";

/**
 * "Model files" on /motion/mediapipe-pose-landmarker-models: the three
 * Pose Landmarker .task bundles on both the `latest` and the versioned `/1/`
 * path, with what a download of each measured — size, SHA-256, the bucket's
 * Last-Modified and ETag headers, and the zip members inside.
 *
 * Every value comes from src/data/poseModelFiles.ts, generated by
 * scripts/fetch-pose-model-files.mjs from the bytes it downloaded; nothing is
 * typed here. The "byte-identical" sentence for each variant is derived from
 * the two hashes in that file, so it changes when a regeneration does.
 *
 * English only: ClusterPage renders it behind `!tr`, and it is not part of the
 * entry's body, so it does not move the page's translation hash.
 */

export const POSE_MODEL_FILES_PATH = "/motion/mediapipe-pose-landmarker-models";

const int = (n: number) => n.toLocaleString("en-US");
const mb = (n: number) => `${(n / 1e6).toFixed(2)} MB`;
const mib = (n: number) => `${(n / 1048576).toFixed(2)} MiB`;
const names = (list: string[]) => (list.length <= 1 ? list.join("") : `${list.slice(0, -1).join(", ")} and ${list[list.length - 1]}`);

function sameVerdict(v: PoseModelVariant): string {
  if (v.identicalToV1) return "The latest and /1/ files are byte-identical: the same SHA-256.";
  const diff =
    v.differingBytes === null
      ? "The two files differ in length"
      : `The two files are the same length and differ in ${int(v.differingBytes)} of ${int(v.latest.bytes)} bytes`;
  if (!v.sameMembers) return `The latest and /1/ files are not byte-identical. ${diff}, and the members inside them differ too.`;
  const times = (f: PoseModelFile) => [...new Set(f.members.map((m) => m.modified))].join(", ");
  return (
    `The latest and /1/ files are not byte-identical. ${diff}; the members inside (${names(v.latest.members.map((m) => m.name))}) ` +
    `have the same SHA-256 in both, and the zip entries' stored modification times differ (${times(v.latest)} in latest, ${times(v.v1)} in /1/).`
  );
}

function UrlLine({ url, label }: { url: string; label: string }) {
  return (
    <div data-copy-scope className="flex items-start gap-2">
      <pre aria-label={label} className="min-w-0 flex-1 overflow-x-auto rounded-lg border border-[var(--border)] bg-[var(--bg)] px-3 py-2 font-mono text-[12px] leading-relaxed text-[var(--fg)]">
        {url}
      </pre>
      <CopyButton label="Copy URL" failed="Select the URL" className="shrink-0 rounded-lg border border-[var(--border)] px-2.5 py-1.5 text-xs font-medium text-[var(--fg)] transition-colors hover:border-brand-400" />
    </div>
  );
}

export default function PoseModelFiles({ path }: { path: string }) {
  if (path !== POSE_MODEL_FILES_PATH) return null;
  const date = formatDate(POSE_MODEL_FILES_FETCHED_ON);
  const identical = POSE_MODEL_FILES.filter((v) => v.identicalToV1).map((v) => v.variant);
  const different = POSE_MODEL_FILES.filter((v) => !v.identicalToV1).map((v) => v.variant);
  const summary =
    different.length === 0
      ? "The latest and /1/ files were byte-identical for all three variants."
      : identical.length === 0
        ? "The latest and /1/ files were not byte-identical for any variant."
        : `The latest and /1/ files were byte-identical for ${names(identical)}, and not for ${names(different)}.`;

  return (
    <section
      id="model-files"
      data-pose-model-files
      className="mt-12 scroll-mt-24 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-5 sm:p-6"
    >
      <h2 className="text-lg font-bold tracking-tight text-[var(--fg)]">Model files, measured {date}</h2>
      <p className="mt-2 text-sm leading-relaxed text-[var(--muted)]">
        We downloaded each file in full on {date}. Sizes and SHA-256 hashes are computed from the bytes received,
        the bundle contents are read from each file&rsquo;s zip directory, and Last-Modified and ETag are the
        storage bucket&rsquo;s response headers, copied as sent. {summary} To pin a file, check its hash after you
        download it (<code className="font-mono text-xs">shasum -a 256 &lt;file&gt;</code>) and serve your copy.
      </p>

      <div className="mt-5 space-y-8">
        {POSE_MODEL_FILES.map((v) => (
          <div key={v.variant} data-pose-model-variant={v.variant}>
            <h3 className="font-mono text-sm font-semibold text-[var(--fg)]">{v.file}</h3>
            <p className="mt-1 text-xs text-[var(--muted)]">
              Inside the latest file: {names(v.latest.members.map((m) => `${m.name} (${int(m.bytes)} bytes)`))}.
            </p>
            <div className="mt-3 overflow-x-auto">
              <table className="w-full min-w-[560px] text-left text-xs">
                <thead className="uppercase tracking-wider text-[var(--muted)]">
                  <tr>
                    <th className="py-2 pr-3">Path</th>
                    <th className="py-2 pr-3 text-right">Bytes</th>
                    <th className="py-2 pr-3 text-right">MB (MiB)</th>
                    <th className="py-2 pr-3">Last-Modified</th>
                    <th className="py-2">ETag</th>
                  </tr>
                </thead>
                <tbody>
                  {[v.latest, v.v1].map((f) => (
                    <tr key={f.version} className="border-t border-[var(--border)] align-top text-[var(--fg)]">
                      <td className="py-2 pr-3 font-mono">{f.version === "latest" ? "float16/latest/" : "float16/1/"}</td>
                      <td className="py-2 pr-3 text-right font-mono">{int(f.bytes)}</td>
                      <td className="py-2 pr-3 text-right font-mono">
                        {mb(f.bytes)} ({mib(f.bytes)})
                      </td>
                      <td className="py-2 pr-3">{f.lastModified ?? "not sent"}</td>
                      <td className="py-2 font-mono">{f.etag ?? "not sent"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <dl className="mt-3 space-y-3 text-xs">
              {[v.latest, v.v1].map((f) => (
                <div key={f.version}>
                  <dt className="font-semibold text-[var(--fg)]">{f.version === "latest" ? "latest" : "/1/ (versioned)"}</dt>
                  <dd className="mt-1 space-y-1.5">
                    <UrlLine url={f.url} label={`${v.file} URL, ${f.version === "latest" ? "latest" : "version 1"} path`} />
                    <p className="break-all text-[var(--muted)]">
                      SHA-256 <span className="font-mono text-[var(--fg)]">{f.sha256}</span>
                    </p>
                  </dd>
                </div>
              ))}
            </dl>
            <p data-pose-model-identical={v.identicalToV1 ? "yes" : "no"} className="mt-3 text-sm text-[var(--fg)]">
              {sameVerdict(v)}
            </p>
          </div>
        ))}
      </div>

      <p className="mt-6 text-xs text-[var(--muted)]">
        Regenerated by <code className="font-mono">scripts/fetch-pose-model-files.mjs</code>, which fails rather than
        publish a partial table if any of the six downloads fails or does not match its Content-Length or the
        bucket&rsquo;s stated MD5. The hashes describe the files on {date}; a later download of a{" "}
        <code className="font-mono">latest</code> URL may not match them.
      </p>
    </section>
  );
}
